-- T30a (D-021): public identifiers. The bigint primary key stays internal; every table whose rows the API exposes
-- gets public_id, a UUID v7 generated by the application (PostgreSQL 17 has no v7 generator), which is the only id
-- that leaves the backend. Users and communities are also addressed by username and slug; communities get one
-- because join, leave, members and delete still take an id.
-- New columns and indexes only; nothing that existed before Flyway is touched (BUG-049).

-- Backfill: a UUID v7 whose time part is the creation time of the row, so existing ids sort like the new ones.
-- (The version/variant bits are set on a random v4 uuid: bits 52-53 turn version 4 into 7.)
CREATE FUNCTION pg_temp.uuid_v7_at(ts timestamptz) RETURNS uuid
LANGUAGE sql VOLATILE AS $$
    SELECT encode(
        set_bit(set_bit(
            overlay(uuid_send(gen_random_uuid())
                    PLACING substring(int8send(floor(extract(epoch FROM ts) * 1000)::bigint) FROM 3) FROM 1 FOR 6),
            52, 1), 53, 1),
        'hex')::uuid
$$;

ALTER TABLE communities   ADD COLUMN public_id uuid;
ALTER TABLE conversations ADD COLUMN public_id uuid;
ALTER TABLE messages      ADD COLUMN public_id uuid;
ALTER TABLE events        ADD COLUMN public_id uuid;

UPDATE communities   SET public_id = pg_temp.uuid_v7_at(created_at::timestamptz);
UPDATE conversations SET public_id = pg_temp.uuid_v7_at(created_at::timestamptz);
UPDATE messages      SET public_id = pg_temp.uuid_v7_at(sent_at::timestamptz);
UPDATE events        SET public_id = pg_temp.uuid_v7_at(created_at);

ALTER TABLE communities   ALTER COLUMN public_id SET NOT NULL;
ALTER TABLE conversations ALTER COLUMN public_id SET NOT NULL;
ALTER TABLE messages      ALTER COLUMN public_id SET NOT NULL;
ALTER TABLE events        ALTER COLUMN public_id SET NOT NULL;

-- The unique indexes are the ones the API looks resources up by
CREATE UNIQUE INDEX uk_communities_public_id   ON communities (public_id);
CREATE UNIQUE INDEX uk_conversations_public_id ON conversations (public_id);
CREATE UNIQUE INDEX uk_messages_public_id      ON messages (public_id);
CREATE UNIQUE INDEX uk_events_public_id        ON events (public_id);
